INSERT INTO `t_announcement` VALUES (2,'新模型上线通知：DeepSeek V4 现已开放使用','  <p>我们已正式接入 <strong>DeepSeek V4</strong> 模型，现向所有用户开放使用。</p>\n\n  <p><strong>DeepSeek V4</strong>\n  是目前性价比最高的大语言模型之一，在代码生成、文本理解、逻辑推理等任务上表现优秀，价格仅为 Claude/GPT 系列的\n  <strong>1/8 至 1/10</strong>，推荐日常任务优先使用。</p>\n\n  <hr style=\"margin: 16px 0; border: none; border-top: 1px solid #eee;\" />\n\n  <p style=\"background:#fff7e6; border-left:4px solid #fa8c16; padding:12px 16px; border-radius:4px; margin:16px 0;\">\n    <strong>⚠️ 重要提示：使用 DeepSeek 前请新开对话窗口</strong><br/>\n    DeepSeek 依赖完整的上下文进行推理。若在已有 Claude 或其他模型的对话中直接切换至\n  DeepSeek，历史消息会一并发送，可能导致模型混淆已有知识或产生意外输出。<br/>\n    <strong>请务必新建一个独立对话窗口后再使用 DeepSeek。</strong>\n  </p>\n\n  <p>如有问题请联系王啸楠。</p>','admin',1,'2026-05-03 22:32:52','2026-05-03 22:32:52');
/*!40000 ALTER TABLE `t_announcement` ENABLE KEYS */;
UNLOCK TABLES;

